const int LED = {{led_pin}};
String buf;

void setup() {
  Serial.begin({{baud}});
  pinMode(LED, OUTPUT);
}

void loop() {
  while (Serial.available()) {
    char c = Serial.read();
    if (c == '\n') {
      if (buf == "on") digitalWrite(LED, HIGH);
      else if (buf == "off") digitalWrite(LED, LOW);
      else Serial.println("unknown");
      buf = "";
    } else buf += c;
  }
}
